const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

// Exercise visibility, permissions and idempotency independently of one another.
for (const role of ['admin', 'editor', 'viewer']) {
  for (const owner of ['actor', 'other']) {
    for (const tenant of ['local', 'foreign']) {
      for (const deleted of [false, true]) {
        for (const archived of [false, true]) {
          const document = { id: 'target', tenant, owner, deleted, archived };
          const unrelated = { id: 'unrelated', tenant: 'local', owner: 'other', deleted: false, archived: false };
          const repo = new DocumentRepository([document, unrelated]);
          repo.audit.push({ actor: 'previous', document: 'previous' });
          const service = new DocumentService(repo);
          const actor = { tenant: 'local', user: 'actor', role };
          const beforeDocuments = structuredClone(repo.documents);
          const beforeAudit = structuredClone(repo.audit);
          const error = deleted || tenant !== actor.tenant
            ? 'not found'
            : role === 'viewer' || (role === 'editor' && owner !== actor.user)
              ? 'forbidden'
              : null;

          if (error) {
            assert.throws(() => service.archive(actor, 'target'), { message: error });
            assert.deepEqual(repo.documents, beforeDocuments);
            assert.deepEqual(repo.audit, beforeAudit);
          } else {
            service.archive(actor, 'target');
            assert.deepEqual(repo.documents, [{ ...beforeDocuments[0], archived: true }, beforeDocuments[1]]);
            const expectedAudit = archived
              ? beforeAudit
              : [...beforeAudit, { actor: actor.user, document: 'target' }];
            assert.deepEqual(repo.audit, expectedAudit);
            service.archive(actor, 'target');
            assert.deepEqual(repo.documents, [{ ...beforeDocuments[0], archived: true }, beforeDocuments[1]]);
            assert.deepEqual(repo.audit, expectedAudit);
          }

          const afterDocuments = structuredClone(repo.documents);
          const afterAudit = structuredClone(repo.audit);
          assert.throws(() => service.archive(actor, 'missing'), { message: 'not found' });
          assert.deepEqual(repo.documents, afterDocuments);
          assert.deepEqual(repo.audit, afterAudit);
        }
      }
    }
  }
}

